const html = `<!doctype html>
<html lang="id">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Analisa Emiten (Tbk) - On Demand</title>
  <style>
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,"Helvetica Neue",Arial; background:#f6f7fb; margin:0;}
    .wrap{max-width:920px;margin:32px auto;padding:0 16px;}
