          <div class="hint">Jika kosong, sistem akan mencoba auto-discovery (best-effort) dari sumber publik.</div>
        </div>

        <div>
          <label for="google_sheet_id">Google Sheet ID harga saham (opsional)</label>
          <input id="google_sheet_id" name="google_sheet_id" placeholder="1AbC... (kosongkan jika tidak ada)" />
          <div class="hint">Tab default: <code>Price5Y</code></div>
        </div>

        <div>
          <label for="sheet_tab_name">Sheet Tab Name (opsional)</label>
          <input id="sheet_tab_name" name="sheet_tab_name" placeholder="Price5Y" />
        </div>

        <div>
          <label for="drive_folder_id">Google Drive Folder ID (opsional)</label>
          <input id="drive_folder_id" name="drive_folder_id" placeholder="1XyZ..." />
