<script>
  const form = document.getElementById('f');
  const ok = document.getElementById('ok');
  const reset = document.getElementById('reset');

  reset.addEventListener('click', () => {
    form.reset();
    ok.style.display='none';
  });

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    ok.style.display='none';

    const fd = new FormData(form);
    const annualRaw = (fd.get('annual_report_urls') || '').toString();
    const annualUrls = annualRaw.split(/\r?\n/).map(s => s.trim()).filter(Boolean);

    const recipientsRaw = (fd.get('recipients_email') || '').toString();
    const recipients = recipientsRaw.split(',').map(s => s.trim()).filter(Boolean);

    const payload = {
      stock_ticker: (fd.get('stock_ticker') || '').toString(),
      company_name: (fd.get('company_name') || '').toString(),
      period_years: parseInt((fd.get('period_years') || '5').toString(), 10),
      news_query: (fd.get('news_query') || '').toString(),
      annual_report_urls: annualUrls,
      google_sheet_id: (fd.get('google_sheet_id') || '').toString(),
      sheet_tab_name: (fd.get('sheet_tab_name') || '').toString(),
      drive_folder_id: (fd.get('drive_folder_id') || '').toString(),
      recipients_email: recipients
    };

    const basePath = window.location.pathname.replace(/\/$/, '');
    const runUrl = basePath + '/run';

    try {
      const res = await fetch(runUrl, {
        method: 'POST',
        headers: {'Content-Type':'application/json'},
        body: JSON.stringify(payload)
      });
      const json = await res.json();
      ok.textContent = 'Selesai. run_id=' + (json.run_id || '-') + (json.drive_links?.report_html ? (' | Drive: ' + json.drive_links.report_html) : '');
      ok.style.display='block';
    } catch(err) {
      ok.textContent = 'Gagal menjalankan analisis: ' + err;
      ok.style.display='block';
    }
  });
</script>
