</html>`;

return [{ json: { html } }];

// Normalize input from webhook (JSON) or schedule trigger
const src = $json?.headers ? 'webhook' : 'schedule';

// Accept both JSON body and query params
const body = $json.body ?? $json;

// Helper: normalize ticker
function normalizeTicker(t) {
  if (!t) return 'IDX:BBCA';
  const s = String(t).trim().toUpperCase();
  if (s.startsWith('IDX:')) return s;
  // if user typed BBCA -> IDX:BBCA
  return 'IDX:' + s.replace(/[^A-Z0-9]/g,'');
}

// Parse annual report urls from text/array
function parseAnnual(v){
  if (!v) return [];
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  const s = String(v);
  return s.split(/\r?\n|,/).map(x => x.trim()).filter(Boolean).filter(u => /^https?:\/\//i.test(u));
}

function parseEmails(v){
  if (!v) return [];
  if (Array.isArray(v)) return v.map(x => String(x).trim()).filter(Boolean);
  return String(v).split(',').map(x=>x.trim()).filter(Boolean);
}

const stock_ticker = normalizeTicker(body.stock_ticker || body.ticker || body.emiten);
const company_name = (body.company_name || '').toString().trim();
const period_years = Number(body.period_years || 5) || 5;

const news_query = (body.news_query || '').toString().trim() || stock_ticker.replace('IDX:','') + ' OR ' + (company_name || stock_ticker.replace('IDX:',''));
const annual_report_urls = parseAnnual(body.annual_report_urls);
const annual_report_keyword = (body.annual_report_keyword || 'laporan tahunan').toString().trim();

const google_sheet_id = (body.google_sheet_id || '').toString().trim();
const sheet_tab_name = (body.sheet_tab_name || 'Price5Y').toString().trim() || 'Price5Y';

const drive_folder_id = (body.drive_folder_id || '').toString().trim();
const recipients_email = parseEmails(body.recipients_email);

const auto_find_annual_reports = body.auto_find_annual_reports === false ? false : true; // default true (best-effort)
const max_news_items = Number(body.max_news_items || 25) || 25;

const bond_identifiers = Array.isArray(body.bond_identifiers) ? body.bond_identifiers : [];
const bond_api_url = (body.bond_api_url || '').toString().trim(); // keep empty by default

const run_id = `${new Date().toISOString().replace(/[-:]/g,'').slice(0,15)}-${stock_ticker.replace('IDX:','')}`;

return [{
  json: {
    __source: src,
    run_id,
    stock_ticker,
    company_name,
    period_years,
    benchmark_ticker: (body.benchmark_ticker || 'IHSG').toString().trim() || 'IHSG',
    news_query,
    annual_report_urls,
    annual_report_keyword,
    auto_find_annual_reports,
    google_sheet_id,
    sheet_tab_name,
    drive_folder_id,
    recipients_email,
    max_news_items,
    bond_identifiers,
    bond_api_url
  }
}];

// Parse IDX company profile response (best-effort)
const config = $('Workflow Configuration').first().json;
const resp = $json || {};
// IDX endpoint often returns { data: [...] } or a list-like structure
const rows = resp.data || resp.Data || resp.rows || resp.items || resp || [];
const arr = Array.isArray(rows) ? rows : (rows?.data ? rows.data : []);
const ticker = config.stock_ticker.replace('IDX:','');

function pickBest(list){
  if (!Array.isArray(list) || list.length===0) return null;
  const byTicker = list.find(x => (x.StockCode || x.Code || x.kodeEmiten || x.stock_code || x.stockCode || '').toString().toUpperCase() === ticker);
  return byTicker || list[0];
}

const best = pickBest(arr);

const company_profile = best ? {
  stock_code: (best.StockCode || best.Code || best.kodeEmiten || best.stock_code || best.stockCode || '').toString(),
  company_name: (best.CompanyName || best.NamaPerusahaan || best.company_name || best.companyName || '').toString(),
  sector: (best.Sector || best.Sektor || best.sector || '').toString(),
  sub_sector: (best.SubSector || best.SubSektor || best.subSector || best.sub_sector || '').toString(),
  listing_date: (best.ListingDate || best.tanggalPencatatan || best.listing_date || '').toString(),
  address: (best.Address || best.Alamat || best.address || '').toString(),
  website: (best.Website || best.website || '').toString(),
} : {};

return [{
  json: {
    company_profile,
    company_name_effective: config.company_name || company_profile.company_name || '',
    stock_ticker: config.stock_ticker,
    run_id: config.run_id
  }
}];

// Parse annual report PDF links from IDX announcement response (best-effort)
const input = $input.first().json;
const resp = $json || {};

function collectUrls(obj){
  const urls = new Set();
  const stack = [obj];
  while (stack.length){
    const cur = stack.pop();
    if (!cur) continue;
    if (typeof cur === 'string'){
      if (/^https?:\/\/\S+\.pdf(\?\S*)?$/i.test(cur)) urls.add(cur);
      continue;
    }
    if (Array.isArray(cur)){
      for (const v of cur) stack.push(v);
      continue;
    }
    if (typeof cur === 'object'){
      for (const k of Object.keys(cur)){
        const v = cur[k];
        // common keys for links
        if (typeof v === 'string' && /pdf/i.test(v)) stack.push(v);
        else stack.push(v);
      }
    }
  }
  return Array.from(urls);
}

const found = collectUrls(resp);
const annual_report_urls = found.slice(0, 5);

return [{
  json: {
    ...input,
    annual_report_urls: annual_report_urls.length ? annual_report_urls : input.annual_report_urls
  }
}];

// Parse and clean stock data from Google Sheets
const items = $input.all();
const cleanedData = [];

// Helper function to detect and remove outliers using IQR method
function removeOutliers(data, field) {
  const values = data.map(item => item[field]).filter(v => v !== null && !isNaN(v)).sort((a, b) => a - b);

  if (values.length < 4) return data; // Not enough data for outlier detection

  const q1Index = Math.floor(values.length * 0.25);
  const q3Index = Math.floor(values.length * 0.75);
  const q1 = values[q1Index];
  const q3 = values[q3Index];
  const iqr = q3 - q1;
  const lowerBound = q1 - (1.5 * iqr);
  const upperBound = q3 + (1.5 * iqr);

  return data.filter(item => {
    const value = item[field];
    return value >= lowerBound && value <= upperBound;
  });
}

// Parse each item
for (const item of items) {
  const json = item.json;

  // Skip header row or empty rows
  if (!json.date || json.date === 'Date' || json.date === 'date') continue;

  try {
    // Parse date - handle various formats
    let dateObj;
    if (json.date instanceof Date) {
      dateObj = json.date;
    } else if (typeof json.date === 'string') {
      dateObj = new Date(json.date);
    } else if (typeof json.date === 'number') {
      // Excel serial date number
      dateObj = new Date((json.date - 25569) * 86400 * 1000);
    }

    // Validate date
    if (!dateObj || isNaN(dateObj.getTime())) continue;

    // Parse numeric values
    const close = parseFloat(json.close || json.Close || json.price || json.Price);
    const volume = parseFloat(json.volume || json.Volume || 0);

    // Skip if close price is invalid
    if (isNaN(close) || close <= 0) continue;

    cleanedData.push({
      date: dateObj,
      close: close,
      volume: isNaN(volume) ? 0 : volume
    });
  } catch (error) {
    console.log(`Error parsing row: ${error.message}`, json);
    continue;
  }
}

// Sort by date ascending
cleanedData.sort((a, b) => a.date - b.date);

// Remove outliers based on close price
const dataWithoutOutliers = removeOutliers(cleanedData, 'close');

// Calculate basic statistics
const closePrices = dataWithoutOutliers.map(d => d.close);
const volumes = dataWithoutOutliers.map(d => d.volume);

const stats = {
  count: dataWithoutOutliers.length,
  priceStats: {
    min: Math.min(...closePrices),
    max: Math.max(...closePrices),
    mean: closePrices.reduce((a, b) => a + b, 0) / closePrices.length,
    median: closePrices.sort((a, b) => a - b)[Math.floor(closePrices.length / 2)]
  },
  volumeStats: {
    min: Math.min(...volumes),
    max: Math.max(...volumes),
    mean: volumes.reduce((a, b) => a + b, 0) / volumes.length,
    total: volumes.reduce((a, b) => a + b, 0)
  },
  dateRange: {
    start: dataWithoutOutliers[0].date,
    end: dataWithoutOutliers[dataWithoutOutliers.length - 1].date
  },
  outliersRemoved: cleanedData.length - dataWithoutOutliers.length
};

console.log('Stock data cleaning complete:', stats);

// Return cleaned data array with statistics
return [
  {
    json: {
      cleanedStockData: dataWithoutOutliers,
      statistics: stats,
      ticker: $('Workflow Configuration').item.json.stock_ticker
    }
  }
];

// Calculate 5-Year Stock Analytics
// Input: Cleaned stock price data from previous node
// Output: Comprehensive analytics object with CAGR, volatility, drawdown, etc.

const items = $input.all();
const stockData = items[0].json.stockData || [];
const benchmarkData = items[0].json.benchmarkData || [];
const config = $('Workflow Configuration').item.json;

// Helper function to calculate returns
function calculateReturns(prices) {
  const returns = [];
  for (let i = 1; i < prices.length; i++) {
    if (prices[i-1] !== 0) {
      returns.push((prices[i] - prices[i-1]) / prices[i-1]);
    }
  }
  return returns;
}

// Helper function to calculate CAGR
function calculateCAGR(startPrice, endPrice, years) {
  if (startPrice <= 0 || endPrice <= 0 || years <= 0) return 0;
  return Math.pow(endPrice / startPrice, 1 / years) - 1;
}

// Helper function to calculate volatility (annualized)
function calculateVolatility(returns) {
  if (returns.length === 0) return 0;
  const mean = returns.reduce((sum, r) => sum + r, 0) / returns.length;
  const variance = returns.reduce((sum, r) => sum + Math.pow(r - mean, 2), 0) / returns.length;
  const dailyVol = Math.sqrt(variance);
  return dailyVol * Math.sqrt(252); // Annualized (252 trading days)
}

// Helper function to calculate max drawdown
function calculateMaxDrawdown(prices) {
  let maxDrawdown = 0;
  let peak = prices[0];
  let peakDate = null;
  let troughDate = null;

  for (let i = 0; i < prices.length; i++) {
    if (prices[i] > peak) {
      peak = prices[i];
      peakDate = stockData[i].date;
    }
    const drawdown = (peak - prices[i]) / peak;
    if (drawdown > maxDrawdown) {
      maxDrawdown = drawdown;
      troughDate = stockData[i].date;
    }
  }

  return { maxDrawdown, peakDate, troughDate };
}

// Helper function to calculate rolling returns
function calculateRollingReturns(prices, period) {
  const rollingReturns = [];
  for (let i = period; i < prices.length; i++) {
    const startPrice = prices[i - period];
    const endPrice = prices[i];
    if (startPrice !== 0) {
      rollingReturns.push((endPrice - startPrice) / startPrice);
    }
  }
  return rollingReturns;
}

// Helper function to calculate moving average
function calculateMA(prices, period) {
  const ma = [];
  for (let i = period - 1; i < prices.length; i++) {
    const sum = prices.slice(i - period + 1, i + 1).reduce((a, b) => a + b, 0);
    ma.push(sum / period);
  }
  return ma;
}

// Helper function to calculate correlation
function calculateCorrelation(returns1, returns2) {
  const n = Math.min(returns1.length, returns2.length);
  if (n === 0) return 0;

  const mean1 = returns1.slice(0, n).reduce((sum, r) => sum + r, 0) / n;
  const mean2 = returns2.slice(0, n).reduce((sum, r) => sum + r, 0) / n;

  let numerator = 0;
  let sum1Sq = 0;
  let sum2Sq = 0;

  for (let i = 0; i < n; i++) {
    const diff1 = returns1[i] - mean1;
    const diff2 = returns2[i] - mean2;
    numerator += diff1 * diff2;
    sum1Sq += diff1 * diff1;
    sum2Sq += diff2 * diff2;
  }

  const denominator = Math.sqrt(sum1Sq * sum2Sq);
  return denominator === 0 ? 0 : numerator / denominator;
}

// Helper function to identify trend phases
function identifyTrendPhases(prices, ma50, ma200) {
  const phases = [];
  let currentPhase = null;

  for (let i = 0; i < prices.length; i++) {
    let phase = 'sideways';

    if (i >= 199) { // Need at least 200 data points for MA200
      const price = prices[i];
      const ma50Val = ma50[i - 49] || price;
      const ma200Val = ma200[i - 199] || price;

      if (price > ma50Val && ma50Val > ma200Val) {
        phase = 'uptrend';
      } else if (price < ma50Val && ma50Val < ma200Val) {
        phase = 'downtrend';
      }
    }

    if (phase !== currentPhase) {
      phases.push({
        phase: phase,
        startDate: stockData[i].date,
        startPrice: prices[i]
      });
      currentPhase = phase;
    }
  }

  return phases;
}

// Extract prices
const prices = stockData.map(d => d.close);
const benchmarkPrices = benchmarkData.map(d => d.close);

// Calculate basic metrics
const startPrice = prices[0];
const endPrice = prices[prices.length - 1];
const years = config.period_years || 5;

const cagr = calculateCAGR(startPrice, endPrice, years);
const totalReturn = (endPrice - startPrice) / startPrice;

// Calculate returns
const returns = calculateReturns(prices);
const benchmarkReturns = calculateReturns(benchmarkPrices);

// Calculate volatility
const volatility = calculateVolatility(returns);

// Calculate max drawdown
const { maxDrawdown, peakDate, troughDate } = calculateMaxDrawdown(prices);

// Calculate rolling returns (assuming ~252 trading days per year)
const rolling1Y = calculateRollingReturns(prices, 252);
const rolling3Y = calculateRollingReturns(prices, 252 * 3);

// Calculate moving averages
const ma50 = calculateMA(prices, 50);
const ma200 = calculateMA(prices, 200);

// Current price vs moving averages
const currentPrice = endPrice;
const currentMA50 = ma50[ma50.length - 1];
const currentMA200 = ma200[ma200.length - 1];

// Calculate correlation with benchmark
const correlation = calculateCorrelation(returns, benchmarkReturns);

// Identify trend phases
const trendPhases = identifyTrendPhases(prices, ma50, ma200);

// Calculate Sharpe Ratio (assuming risk-free rate of 6% for Indonesia)
const riskFreeRate = 0.06;
const excessReturn = cagr - riskFreeRate;
const sharpeRatio = volatility !== 0 ? excessReturn / volatility : 0;

// Calculate beta (vs benchmark)
const benchmarkVolatility = calculateVolatility(benchmarkReturns);
const beta = benchmarkVolatility !== 0 ? (correlation * volatility) / benchmarkVolatility : 1;

// Compile comprehensive analytics
const analytics = {
  ticker: config.stock_ticker,
  companyName: config.company_name,
  analysisDate: $now.toISO(),
  periodYears: years,

  priceMetrics: {
    startPrice: startPrice,
    endPrice: endPrice,
    currentPrice: currentPrice,
    startDate: stockData[0].date,
    endDate: stockData[stockData.length - 1].date
  },

  returnMetrics: {
    cagr: cagr,
    cagrPercent: (cagr * 100).toFixed(2) + '%',
    totalReturn: totalReturn,
    totalReturnPercent: (totalReturn * 100).toFixed(2) + '%',
    rolling1YAvg: rolling1Y.length > 0 ? rolling1Y.reduce((a, b) => a + b, 0) / rolling1Y.length : 0,
    rolling3YAvg: rolling3Y.length > 0 ? rolling3Y.reduce((a, b) => a + b, 0) / rolling3Y.length : 0
  },

  riskMetrics: {
    annualizedVolatility: volatility,
    volatilityPercent: (volatility * 100).toFixed(2) + '%',
    maxDrawdown: maxDrawdown,
    maxDrawdownPercent: (maxDrawdown * 100).toFixed(2) + '%',
    maxDrawdownPeakDate: peakDate,
    maxDrawdownTroughDate: troughDate,
    sharpeRatio: sharpeRatio,
    beta: beta
  },

  technicalIndicators: {
    ma50: currentMA50,
    ma200: currentMA200,
    priceVsMA50: ((currentPrice - currentMA50) / currentMA50 * 100).toFixed(2) + '%',
    priceVsMA200: ((currentPrice - currentMA200) / currentMA200 * 100).toFixed(2) + '%',
    goldenCross: currentMA50 > currentMA200,
    currentTrend: trendPhases[trendPhases.length - 1]?.phase || 'unknown'
  },

  benchmarkComparison: {
    benchmark: config.benchmark_ticker,
    correlation: correlation,
    correlationPercent: (correlation * 100).toFixed(2) + '%',
    beta: beta,
    benchmarkCAGR: calculateCAGR(benchmarkPrices[0], benchmarkPrices[benchmarkPrices.length - 1], years),
    outperformance: cagr - calculateCAGR(benchmarkPrices[0], benchmarkPrices[benchmarkPrices.length - 1], years)
  },

  trendPhases: trendPhases,

  rawData: {
    prices: prices,
    returns: returns,
    ma50: ma50,
    ma200: ma200,
    rolling1Y: rolling1Y,
    rolling3Y: rolling3Y
  }
};

return [{ json: { analytics: analytics, stockData: stockData, benchmarkData: benchmarkData } }];

// Provide empty stock analytics if no stock price dataset is provided
const config = $('Workflow Configuration').first().json;
return [{
  json: {
    stock_analytics: null,
    stock_datapoints: 0,
    note: 'Stock price analytics skipped (google_sheet_id not provided).',
    stock_ticker: config.stock_ticker,
    run_id: config.run_id
  }
}];

// Deduplicate news by URL, clean HTML entities, extract fields, and sort by date
const items = $input.all();
