// Keywords for SWOT classification
const swotKeywords = {
  strength: ['pertumbuhan', 'meningkat', 'ekspansi', 'inovasi', 'penghargaan', 'prestasi', 'keunggulan', 'unggul', 'sukses', 'profit', 'laba', 'dividen', 'akuisisi', 'kemitraan', 'kolaborasi'],
