  makro: ['ekonomi', 'inflasi', 'suku bunga', 'nilai tukar', 'GDP', 'resesi', 'pertumbuhan ekonomi', 'makro']
};

// Function to calculate keyword matches
function countKeywordMatches(text, keywords) {
  const lowerText = text.toLowerCase();
  return keywords.filter(keyword => lowerText.includes(keyword.toLowerCase())).length;
}

// Function to determine SWOT category
function classifySWOT(title, description) {
  const text = `${title} ${description}`.toLowerCase();
  const scores = {
    strength: countKeywordMatches(text, swotKeywords.strength),
    weakness: countKeywordMatches(text, swotKeywords.weakness),
    opportunity: countKeywordMatches(text, swotKeywords.opportunity),
    threat: countKeywordMatches(text, swotKeywords.threat)
  };

  const maxScore = Math.max(...Object.values(scores));
  if (maxScore === 0) return 'opportunity'; // Default to opportunity if no keywords match

  return Object.keys(scores).find(key => scores[key] === maxScore);
}

// Function to determine theme
function classifyTheme(title, description) {
  const text = `${title} ${description}`.toLowerCase();
  const scores = {};

  for (const [theme, keywords] of Object.entries(themeKeywords)) {
    scores[theme] = countKeywordMatches(text, keywords);
  }

  const maxScore = Math.max(...Object.values(scores));
  if (maxScore === 0) return 'operasional'; // Default theme

  return Object.keys(scores).find(key => scores[key] === maxScore);
}

// Function to calculate sentiment score (-1 to 1)
function calculateSentiment(title, description, swotCategory) {
  const text = `${title} ${description}`.toLowerCase();

  const positiveWords = ['baik', 'positif', 'meningkat', 'tumbuh', 'sukses', 'untung', 'laba', 'naik', 'optimis', 'kuat'];
  const negativeWords = ['buruk', 'negatif', 'turun', 'merosot', 'rugi', 'gagal', 'lemah', 'pesimis', 'krisis', 'masalah'];

  const positiveCount = countKeywordMatches(text, positiveWords);
  const negativeCount = countKeywordMatches(text, negativeWords);

  let sentiment = (positiveCount - negativeCount) / Math.max(positiveCount + negativeCount, 1);

  // Adjust based on SWOT category
  if (swotCategory === 'strength') sentiment = Math.max(sentiment, 0.3);
  if (swotCategory === 'weakness' || swotCategory === 'threat') sentiment = Math.min(sentiment, -0.2);
  if (swotCategory === 'opportunity') sentiment = Math.max(sentiment, 0.1);

  return Math.max(-1, Math.min(1, sentiment));
}

// Function to calculate materiality score (0-10)
function calculateMateriality(title, description, theme) {
  const text = `${title} ${description}`.toLowerCase();

  const highImpactWords = ['signifikan', 'besar', 'utama', 'penting', 'krusial', 'strategis', 'fundamental', 'drastis'];
  const financialWords = ['miliar', 'triliun', 'juta', 'persen', '%', 'revenue', 'laba', 'rugi'];

  let score = 5; // Base score

  // Increase score for high impact words
  score += countKeywordMatches(text, highImpactWords) * 1.5;

  // Increase score for financial mentions
  score += countKeywordMatches(text, financialWords) * 1;

  // Adjust based on theme importance
  const themeWeights = {
    keuangan: 1.5,
    regulasi: 1.3,
    manajemen: 1.2,
    operasional: 1.0,
    kompetisi: 1.1,
    teknologi: 0.9,
    reputasi: 1.0,
    ESG: 0.8,
    makro: 1.2
  };

  score *= (themeWeights[theme] || 1.0);

  return Math.max(0, Math.min(10, Math.round(score * 10) / 10));
}

