// Extract Financial Ratios from Annual Reports (5 Years)
// Input: Extracted text from annual reports
// Output: Structured 5-year financial data with ratios and notes

const items = $input.all();
const config = $('Workflow Configuration').first().json;
const financialData = [];

// Helper function to extract numbers from text
function extractNumber(text, pattern) {
  const match = text.match(pattern);
  if (match) {
    // Remove commas, dots (except decimal), and convert to number
    const numStr = match[1].replace(/[,\s]/g, '').replace(/\./g, '');
    return parseFloat(numStr) || 0;
  }
  return 0;
}

// Helper function to find value in table-like structures
function findFinancialValue(text, keywords, year) {
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].toLowerCase();
    if (keywords.some(kw => line.includes(kw.toLowerCase()))) {
      // Look for numbers in current line or next few lines
      for (let j = i; j < Math.min(i + 5, lines.length); j++) {
        const numMatch = lines[j].match(/([\d,\.]+)/);
        if (numMatch) {
          const num = parseFloat(numMatch[1].replace(/[,]/g, ''));
          if (num > 0) return num;
        }
      }
    }
  }
  return 0;
}

// Process each annual report
for (let i = 0; i < items.length && i < 5; i++) {
  const item = items[i];
  const text = item.json.text || item.json.data || '';
  const year = new Date().getFullYear() - (4 - i); // Last 5 years

  // Extract Income Statement items (in millions)
  const revenue = findFinancialValue(text, ['pendapatan', 'revenue', 'penjualan', 'sales'], year) || 
                  extractNumber(text, /(?:pendapatan|revenue|penjualan)[\s\S]{0,200}?([\d,\.]+)/);

  const cogs = findFinancialValue(text, ['beban pokok', 'cost of goods', 'harga pokok'], year) ||
               extractNumber(text, /(?:beban pokok|cost of goods)[\s\S]{0,200}?([\d,\.]+)/);

  const grossProfit = revenue - cogs;

  const operatingExpenses = findFinancialValue(text, ['beban operasi', 'operating expense', 'beban usaha'], year) ||
                            extractNumber(text, /(?:beban operasi|operating expense)[\s\S]{0,200}?([\d,\.]+)/);

  const ebit = findFinancialValue(text, ['ebit', 'laba operasi', 'operating income'], year) ||
               grossProfit - operatingExpenses;

  const interestExpense = findFinancialValue(text, ['beban bunga', 'interest expense', 'biaya bunga'], year) ||
                          extractNumber(text, /(?:beban bunga|interest expense)[\s\S]{0,200}?([\d,\.]+)/);

  const netProfit = findFinancialValue(text, ['laba bersih', 'net profit', 'net income', 'laba tahun berjalan'], year) ||
                    extractNumber(text, /(?:laba bersih|net profit|net income)[\s\S]{0,200}?([\d,\.]+)/);

  // Extract Balance Sheet items (in millions)
  const totalAssets = findFinancialValue(text, ['total aset', 'total assets', 'jumlah aset'], year) ||
                      extractNumber(text, /(?:total aset|total assets)[\s\S]{0,200}?([\d,\.]+)/);

  const currentAssets = findFinancialValue(text, ['aset lancar', 'current assets', 'aktiva lancar'], year) ||
                        extractNumber(text, /(?:aset lancar|current assets)[\s\S]{0,200}?([\d,\.]+)/);

  const totalLiabilities = findFinancialValue(text, ['total liabilitas', 'total liabilities', 'total kewajiban'], year) ||
                           extractNumber(text, /(?:total liabilitas|total liabilities)[\s\S]{0,200}?([\d,\.]+)/);

  const currentLiabilities = findFinancialValue(text, ['liabilitas jangka pendek', 'current liabilities', 'kewajiban lancar'], year) ||
                             extractNumber(text, /(?:liabilitas jangka pendek|current liabilities)[\s\S]{0,200}?([\d,\.]+)/);

  const totalDebt = findFinancialValue(text, ['total utang', 'total debt', 'pinjaman'], year) ||
                    extractNumber(text, /(?:total utang|total debt|pinjaman)[\s\S]{0,200}?([\d,\.]+)/);

  const equity = findFinancialValue(text, ['total ekuitas', 'total equity', 'modal'], year) ||
                 totalAssets - totalLiabilities;

  const cash = findFinancialValue(text, ['kas dan setara kas', 'cash and cash equivalents', 'kas'], year) ||
               extractNumber(text, /(?:kas dan setara kas|cash and cash equivalents)[\s\S]{0,200}?([\d,\.]+)/);

  // Extract Cash Flow items (in millions)
  const cfo = findFinancialValue(text, ['arus kas operasi', 'cash flow from operating', 'operating cash flow'], year) ||
              extractNumber(text, /(?:arus kas operasi|operating activities)[\s\S]{0,200}?([\d,\.]+)/);

  const cfi = findFinancialValue(text, ['arus kas investasi', 'cash flow from investing', 'investing cash flow'], year) ||
              extractNumber(text, /(?:arus kas investasi|investing activities)[\s\S]{0,200}?([\d,\.]+)/);

  const cff = findFinancialValue(text, ['arus kas pendanaan', 'cash flow from financing', 'financing cash flow'], year) ||
              extractNumber(text, /(?:arus kas pendanaan|financing activities)[\s\S]{0,200}?([\d,\.]+)/);

  // Calculate Financial Ratios
  const grossMargin = revenue > 0 ? (grossProfit / revenue) * 100 : 0;
  const operatingMargin = revenue > 0 ? (ebit / revenue) * 100 : 0;
  const netMargin = revenue > 0 ? (netProfit / revenue) * 100 : 0;

  const roa = totalAssets > 0 ? (netProfit / totalAssets) * 100 : 0;
  const roe = equity > 0 ? (netProfit / equity) * 100 : 0;

  const debtToEquity = equity > 0 ? totalDebt / equity : 0;
  const debtToAssets = totalAssets > 0 ? totalDebt / totalAssets : 0;

  const currentRatio = currentLiabilities > 0 ? currentAssets / currentLiabilities : 0;
  const quickRatio = currentLiabilities > 0 ? (currentAssets - (currentAssets * 0.3)) / currentLiabilities : 0; // Approximation

  const interestCoverage = interestExpense > 0 ? ebit / interestExpense : 0;
  const assetTurnover = totalAssets > 0 ? revenue / totalAssets : 0;

  // Extract qualitative notes
  const debtMaturityNotes = text.match(/(?:jatuh tempo|maturity|pelunasan utang)[\s\S]{0,500}/gi)?.[0] || 'Not found';
  const capexNotes = text.match(/(?:belanja modal|capital expenditure|capex|investasi aset)[\s\S]{0,500}/gi)?.[0] || 'Not found';
  const litigationNotes = text.match(/(?:litigasi|litigation|gugatan|perkara hukum)[\s\S]{0,500}/gi)?.[0] || 'No litigation mentioned';
  const esgNotes = text.match(/(?:keberlanjutan|sustainability|esg|lingkungan|sosial|tata kelola)[\s\S]{0,500}/gi)?.[0] || 'Not found';
  const corporateActionsNotes = text.match(/(?:aksi korporasi|corporate action|dividen|stock split|rights issue)[\s\S]{0,500}/gi)?.[0] || 'Not found';

  // Compile financial data for this year
  financialData.push({
    year: year,
    // Income Statement
    revenue: revenue,
    cogs: cogs,
    grossProfit: grossProfit,
    operatingExpenses: operatingExpenses,
    ebit: ebit,
    interestExpense: interestExpense,
    netProfit: netProfit,

    // Balance Sheet
    totalAssets: totalAssets,
    currentAssets: currentAssets,
    totalLiabilities: totalLiabilities,
    currentLiabilities: currentLiabilities,
    totalDebt: totalDebt,
    equity: equity,
    cash: cash,

    // Cash Flow
    cfo: cfo,
    cfi: cfi,
    cff: cff,

    // Profitability Ratios
    grossMargin: Math.round(grossMargin * 100) / 100,
    operatingMargin: Math.round(operatingMargin * 100) / 100,
    netMargin: Math.round(netMargin * 100) / 100,

    // Return Ratios
    roa: Math.round(roa * 100) / 100,
    roe: Math.round(roe * 100) / 100,

    // Leverage Ratios
    debtToEquity: Math.round(debtToEquity * 100) / 100,
    debtToAssets: Math.round(debtToAssets * 100) / 100,

    // Liquidity Ratios
    currentRatio: Math.round(currentRatio * 100) / 100,
    quickRatio: Math.round(quickRatio * 100) / 100,

    // Other Ratios
    interestCoverage: Math.round(interestCoverage * 100) / 100,
    assetTurnover: Math.round(assetTurnover * 100) / 100,

    // Qualitative Notes
    notes: {
      debtMaturity: debtMaturityNotes.substring(0, 500),
      capex: capexNotes.substring(0, 500),
      litigation: litigationNotes.substring(0, 500),
      esg: esgNotes.substring(0, 500),
      corporateActions: corporateActionsNotes.substring(0, 500)
    }
  });
}

