// Prepare 3 upload items (report_html, report_json, raw_payload) using a single binary field name: file
const cfg = $('Workflow Configuration').first().json;
const fmt = $input.first(); // from Format Report (HTML + JSON)
const bin = fmt.binary || {};

let ctx = {};
try { ctx = $('Assemble Analysis Context').first().json.context || {}; } catch(e) {}
const payload = { config: cfg, context: ctx, generated_at: new Date().toISOString() };
const rawBin = Buffer.from(JSON.stringify(payload, null, 2), 'utf-8').toString('base64');

const items = [];

if (bin.report_html) {
  items.push({ json: { kind: 'report_html', run_id: cfg.run_id }, binary: { file: { ...bin.report_html } } });
}
if (bin.report_json) {
  items.push({ json: { kind: 'report_json', run_id: cfg.run_id }, binary: { file: { ...bin.report_json } } });
}
items.push({
  json: { kind: 'raw_payload', run_id: cfg.run_id },
  binary: {
    file: {
      data: rawBin,
      mimeType: 'application/json',
      fileName: `${cfg.run_id}_RawPayload.json`
    }
  }
});

return items;

// Collect Drive links from uploaded items
const items = $input.all();
const links = {};
for (const it of items) {
  const kind = it.json.kind;
  const j = it.json || {};
  // googleDrive node output fields often include id, webViewLink, webContentLink
  const link = j.webViewLink || j.webContentLink || j.id || null;
  if (kind) links[kind] = link;
}
return [{
  json: { drive_links: links }
}];
